mapper.select:
SELECT
    ROUND(AVG(
        UNIX_TIMESTAMP(finish_time) * 1000 - UNIX_TIMESTAMP(create_time) * 1000
    )) AS avg_duration_ms,
    ROUND(MAX(
        UNIX_TIMESTAMP(finish_time) * 1000 - UNIX_TIMESTAMP(create_time) * 1000
    )) AS max_duration_ms,
    ROUND(MIN(
        UNIX_TIMESTAMP(finish_time) * 1000 - UNIX_TIMESTAMP(create_time) * 1000
    )) AS min_duration_ms
FROM t_transaction
WHERE is_delete = 0
AND status = 2
AND finish_time IS NOT NULL

AND accounting_date >= #{startDate}


AND accounting_date <= #{endDate}


AND business_code = #{businessCode}
